// C5: solo se aceptan avisos con el token de Zabbix.
const entrada = $input.first().json;
const cab = entrada.headers || {};
const b = entrada.body || {};
if (!cab['x-zabbix-token'] || cab['x-zabbix-token'] !== $env.WEBHOOK_TOKEN) {
  return [{ json: { accion: 'rechazar', motivo: 'token inválido: aviso descartado', event_id: null } }];
}

let tags = [];
try { tags = typeof b.tags === 'string' ? JSON.parse(b.tags) : (b.tags || []); } catch (e) { tags = []; }
const tag = (n) => (tags.find((t) => t.tag === n) || {}).value;
const remediation = tag('remediation') || 'none';
const target = tag('target') || '';

// C1: lista cerrada. El comando sale de esta tabla, NUNCA del texto recibido.
const PERMITIDOS = {
  'restart-container': { 'msmotos-app': 'sudo /usr/bin/docker start msmotos-app' },
  'restart-service': { 'nginx': 'sudo /usr/bin/systemctl restart nginx' },
};

const esProblema = String(b.event_value) === '1';
let accion = 'notificar';
let comando = null;
let motivo = '';

if (esProblema && remediation !== 'none') {
  comando = (PERMITIDOS[remediation] || {})[target] || null;
  if (!comando) {
    motivo = `acción rechazada: ${remediation}/${target} no está en la lista permitida`;
  } else {
    // C2 y C3: máximo 3 intentos por objetivo cada 10 minutos; luego se escala a una persona.
    const estado = $getWorkflowStaticData('global');
    const clave = `${remediation}:${target}`;
    const ahora = Date.now();
    const recientes = (estado[clave] || []).filter((t) => ahora - t < 10 * 60 * 1000);
    if (recientes.length >= 3) {
      accion = 'escalar';
      comando = null;
      motivo = 'recuperación automática agotada (3 intentos en 10 min): requiere intervención humana';
    } else {
      recientes.push(ahora);
      estado[clave] = recientes;
      accion = 'recuperar';
      motivo = `intento ${recientes.length} de 3`;
    }
  }
}

return [{ json: {
  accion, motivo, comando, remediation, target,
  event_id: b.event_id, event_value: String(b.event_value), severity: b.severity,
  host: b.host, trigger: b.trigger, time: b.time,
} }];

const d = $('Validar y decidir').first().json;
const r = $input.first().json;
const ok = r.code === 0 && !r.error;
const detalle = ok ? 'comando ejecutado' : `falló: ${(r.stderr || r.error?.message || r.error || 'sin detalle')}`;
return [{ json: {
  ...d,
  resultado: ok ? 'OK' : 'FALLO',
  mensaje: `🔧 [${d.severity}] ${d.trigger} · ${d.host} · recuperación automática (${d.motivo}): ${detalle}`,
} }];

const d = $input.first().json;
const icono = d.accion === 'rechazar' ? '⛔ RECHAZADO'
  : d.event_value === '0' ? '✅ RESUELTO'
  : d.accion === 'escalar' ? '🚨 ESCALAR A HUMANO'
  : '🔴 PROBLEMA';
return [{ json: {
  ...d,
  mensaje: `${icono} [${d.severity || '-'}] ${d.trigger || ''} · ${d.host || ''} · ${d.time || ''}${d.motivo ? ' · ' + d.motivo : ''}`,
} }];
